CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE "user" (
 id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL,
 email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 two_factor_enabled boolean DEFAULT false
);
CREATE TABLE session (
 id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text UNIQUE NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 ip_address text, user_agent text, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE
);
CREATE INDEX session_user_idx ON session(user_id);
CREATE TABLE account (
 id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE verification (
 id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX verification_identifier_idx ON verification(identifier);
CREATE TABLE two_factor (
 id text PRIMARY KEY, secret text NOT NULL, backup_codes text NOT NULL, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, verified boolean
);
CREATE INDEX two_factor_user_idx ON two_factor(user_id);
CREATE TABLE user_roles (user_id text NOT NULL REFERENCES "user"(id), role text NOT NULL CHECK(role IN ('USER','ARTIST','AGENT','GALLERY_MEMBER','COLLECTOR','ADVISER','INSTITUTION_MEMBER','MODERATOR','CURATOR','EDITOR','OPERATIONS','ADMIN','SUPERADMIN')), assigned_by text REFERENCES "user"(id), assigned_at timestamptz DEFAULT now(), PRIMARY KEY(user_id,role));
CREATE TABLE profiles (user_id text PRIMARY KEY REFERENCES "user"(id), public_display_name text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', visibility text NOT NULL DEFAULT 'OWNER_AND_STAFF', contact_access text NOT NULL DEFAULT 'PRIVATE', collection_visibility text NOT NULL DEFAULT 'OWNER_AND_STAFF', interests jsonb DEFAULT '[]', updated_at timestamptz DEFAULT now());
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, type text NOT NULL CHECK(type IN ('GALLERY','AGENCY','MUSEUM','FOUNDATION')), description text NOT NULL DEFAULT '', verification_status text NOT NULL DEFAULT 'UNVERIFIED', country text NOT NULL DEFAULT 'RU', website text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now());
CREATE TABLE organization_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id text NOT NULL REFERENCES "user"(id), role text NOT NULL, invitation_status text NOT NULL DEFAULT 'ACCEPTED', UNIQUE(organization_id,user_id));
CREATE TABLE verification_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id text NOT NULL, requested_by text NOT NULL REFERENCES "user"(id), status text NOT NULL DEFAULT 'SUBMITTED', reviewed_by text REFERENCES "user"(id), notes_private text, created_at timestamptz DEFAULT now(), reviewed_at timestamptz);
CREATE TABLE artists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text UNIQUE REFERENCES "user"(id), name text NOT NULL, slug text UNIQUE NOT NULL, biography text NOT NULL DEFAULT '', statement text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', verification_status text NOT NULL DEFAULT 'UNVERIFIED', created_at timestamptz DEFAULT now());
CREATE TABLE series (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artist_id uuid NOT NULL REFERENCES artists(id), title text NOT NULL, slug text UNIQUE NOT NULL, statement text NOT NULL DEFAULT '', year_start int, year_end int, visibility text NOT NULL DEFAULT 'PUBLIC', created_at timestamptz DEFAULT now());
CREATE TABLE artworks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artist_id uuid NOT NULL REFERENCES artists(id), series_id uuid REFERENCES series(id), title text NOT NULL, slug text UNIQUE NOT NULL, capture_year int NOT NULL CHECK(capture_year BETWEEN 1800 AND 2200), description text NOT NULL, genre text NOT NULL DEFAULT '', color_mode text NOT NULL CHECK(color_mode IN ('COLOR','BW')), editorial_status text NOT NULL DEFAULT 'DRAFT' CHECK(editorial_status IN ('DRAFT','SUBMITTED','NEEDS_CHANGES','APPROVED','REJECTED','PUBLISHED','ARCHIVED')), visibility text NOT NULL DEFAULT 'PUBLIC' CHECK(visibility IN ('PUBLIC','UNLISTED','VERIFIED_ONLY','INVITED_ONLY','OWNER_AND_STAFF')), rights_status text NOT NULL DEFAULT 'DECLARED', is_curated boolean NOT NULL DEFAULT false, authenticity_status text NOT NULL DEFAULT 'UNVERIFIED', version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), search_vector tsvector GENERATED ALWAYS AS (to_tsvector('russian', coalesce(title,'') || ' ' || coalesce(description,'') || ' ' || coalesce(genre,''))) STORED);
CREATE INDEX artwork_public_idx ON artworks(editorial_status,visibility);
CREATE INDEX artwork_artist_idx ON artworks(artist_id,created_at);
CREATE INDEX artwork_search_idx ON artworks USING gin(search_vector);
CREATE TABLE representation_mandates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artist_id uuid NOT NULL REFERENCES artists(id), organization_id uuid NOT NULL REFERENCES organizations(id), artwork_id uuid REFERENCES artworks(id), exclusive boolean NOT NULL DEFAULT false, geography text NOT NULL DEFAULT 'RU', scope text NOT NULL DEFAULT 'SALE', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL CHECK(ends_at>starts_at), status text NOT NULL DEFAULT 'PENDING', evidence text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE edition_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artwork_id uuid NOT NULL REFERENCES artworks(id), print_technique text NOT NULL, paper text NOT NULL, image_width_mm int NOT NULL CHECK(image_width_mm>0), image_height_mm int NOT NULL CHECK(image_height_mm>0), sheet_width_mm int NOT NULL CHECK(sheet_width_mm>=image_width_mm), sheet_height_mm int NOT NULL CHECK(sheet_height_mm>=image_height_mm), edition_type text NOT NULL CHECK(edition_type IN ('LIMITED','OPEN')), edition_total int, ap_total int NOT NULL DEFAULT 0 CHECK(ap_total>=0), signed boolean NOT NULL DEFAULT false, CHECK((edition_type='LIMITED' AND edition_total>0) OR (edition_type='OPEN' AND edition_total IS NULL)));
CREATE TABLE edition_copies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variant_id uuid NOT NULL REFERENCES edition_variants(id), number int, proof_type text NOT NULL DEFAULT 'REGULAR' CHECK(proof_type IN ('REGULAR','AP')), condition text NOT NULL DEFAULT 'NEW', print_year int NOT NULL, status text NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','RESERVED','SOLD','ON_HOLD')), UNIQUE(variant_id,number,proof_type));
CREATE TABLE artwork_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artwork_id uuid NOT NULL REFERENCES artworks(id), storage_key_original text NOT NULL, derivative_key text NOT NULL, thumbnail_key text NOT NULL, alt_text text NOT NULL, rights_holder text NOT NULL, mime_type text NOT NULL, sort_order int DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES "user"(id), storage_key text NOT NULL, document_type text NOT NULL, access_level text NOT NULL DEFAULT 'OWNER_AND_STAFF', verification_status text NOT NULL DEFAULT 'UNVERIFIED', created_at timestamptz DEFAULT now());
CREATE TABLE provenance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), copy_id uuid NOT NULL REFERENCES edition_copies(id), description text NOT NULL, source text NOT NULL, visibility text NOT NULL DEFAULT 'OWNER_AND_STAFF', verification_status text NOT NULL DEFAULT 'UNVERIFIED');
CREATE TABLE listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), edition_copy_id uuid NOT NULL REFERENCES edition_copies(id), edition_variant_id uuid NOT NULL REFERENCES edition_variants(id), seller_id text NOT NULL REFERENCES "user"(id), representative_org_id uuid REFERENCES organizations(id), market_type text NOT NULL DEFAULT 'PRIMARY_MARKET', price_mode text NOT NULL CHECK(price_mode IN ('FIXED_PRICE','PRICE_ON_REQUEST','NOT_FOR_SALE')), price_minor bigint CHECK(price_minor>0 AND price_minor<=9000000000000), currency text NOT NULL DEFAULT 'RUB' CHECK(currency='RUB'), visibility text NOT NULL DEFAULT 'PUBLIC', status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ON_HOLD','ARCHIVED')), rights_evidence text NOT NULL, verified_rights_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(price_mode!='FIXED_PRICE' OR price_minor IS NOT NULL));
CREATE INDEX listing_status_price_idx ON listings(status,price_minor);
CREATE TABLE commission_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, version int NOT NULL, basis_points int CHECK(basis_points BETWEEN 0 AND 10000), is_demo boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'DRAFT', created_at timestamptz DEFAULT now(), UNIQUE(name,version));
CREATE TABLE inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL REFERENCES "user"(id), listing_id uuid NOT NULL REFERENCES listings(id), type text NOT NULL, status text NOT NULL DEFAULT 'NEW', contact_preference text NOT NULL DEFAULT 'IN_PLATFORM', assignee_id text REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inquiry_listing_idx ON inquiries(listing_id,status);
CREATE TABLE inquiry_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inquiry_id uuid NOT NULL REFERENCES inquiries(id), author_id text NOT NULL REFERENCES "user"(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inquiry_id uuid NOT NULL REFERENCES inquiries(id), amount_minor bigint NOT NULL CHECK(amount_minor>0 AND amount_minor<=9000000000000), currency text NOT NULL DEFAULT 'RUB', valid_until timestamptz NOT NULL, terms text NOT NULL, commission_policy_id uuid NOT NULL REFERENCES commission_policies(id), commission_snapshot jsonb NOT NULL, status text NOT NULL DEFAULT 'OFFERED', created_at timestamptz DEFAULT now());
CREATE TABLE reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), edition_copy_id uuid NOT NULL REFERENCES edition_copies(id), listing_id uuid NOT NULL REFERENCES listings(id), buyer_id text NOT NULL REFERENCES "user"(id), expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','EXPIRED','COMPLETED','CANCELLED')), created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX one_active_reservation_per_copy ON reservations(edition_copy_id) WHERE status='ACTIVE';
CREATE INDEX reservation_expiration_idx ON reservations(expires_at) WHERE status='ACTIVE';
CREATE TABLE deals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inquiry_id uuid NOT NULL REFERENCES inquiries(id), offer_id uuid UNIQUE NOT NULL REFERENCES offers(id), listing_id uuid NOT NULL REFERENCES listings(id), edition_copy_id uuid NOT NULL REFERENCES edition_copies(id), reservation_id uuid NOT NULL REFERENCES reservations(id), buyer_id text NOT NULL REFERENCES "user"(id), seller_id text NOT NULL REFERENCES "user"(id), status text NOT NULL DEFAULT 'OFFLINE_AGREED' CHECK(status IN ('OFFLINE_AGREED','OFFLINE_COMPLETION_PENDING_VERIFICATION','OFFLINE_CONFIRMED','CANCELLED','EXPIRED')), settlement_mode text NOT NULL DEFAULT 'OFFLINE' CHECK(settlement_mode='OFFLINE'), amount_minor bigint NOT NULL, currency text NOT NULL DEFAULT 'RUB', commission_snapshot jsonb NOT NULL, terms_snapshot text NOT NULL, evidence text, confirmed_by text REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deal_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deal_id uuid NOT NULL REFERENCES deals(id), event_type text NOT NULL, actor_id text REFERENCES "user"(id), details jsonb NOT NULL DEFAULT '{}', at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operation_keys (actor_id text NOT NULL REFERENCES "user"(id), operation text NOT NULL, key text NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, created_at timestamptz DEFAULT now(), PRIMARY KEY(actor_id,operation,key));
CREATE TABLE open_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, slug text UNIQUE NOT NULL, organizer_name text NOT NULL, source_type text NOT NULL CHECK(source_type IN ('EXTERNAL','VERSUS_HOSTED')), source_url text, description text NOT NULL, requirements text NOT NULL, eligibility text NOT NULL DEFAULT '', fee_minor bigint NOT NULL DEFAULT 0, location text NOT NULL DEFAULT 'Онлайн', online_allowed boolean NOT NULL DEFAULT true, starts_at timestamptz NOT NULL, deadline_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'Europe/Moscow', status text NOT NULL DEFAULT 'PUBLISHED', max_works int NOT NULL DEFAULT 10 CHECK(max_works BETWEEN 1 AND 20), max_applications int NOT NULL DEFAULT 1 CHECK(max_applications BETWEEN 1 AND 5), last_checked_at timestamptz, is_demo boolean NOT NULL DEFAULT false, CHECK(deadline_at>starts_at));
CREATE INDEX call_deadline_idx ON open_calls(deadline_at,status);
CREATE TABLE applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), applicant_id text NOT NULL REFERENCES "user"(id), open_call_id uuid NOT NULL REFERENCES open_calls(id), statement text NOT NULL, work_ids uuid[] NOT NULL, rules_accepted boolean NOT NULL CHECK(rules_accepted), data_consent boolean NOT NULL CHECK(data_consent), status text NOT NULL DEFAULT 'SUBMITTED', receipt uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), submitted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private_memberships (user_id text PRIMARY KEY REFERENCES "user"(id), status text NOT NULL CHECK(status IN ('INVITED','APPLIED','APPROVED','SUSPENDED','REVOKED')), approved_by text REFERENCES "user"(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz, invited_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE curated_collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL, visibility text NOT NULL CHECK(visibility IN ('PUBLIC','INVITED_ONLY')), status text NOT NULL DEFAULT 'PUBLISHED', curator_id text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE curated_collection_items (collection_id uuid NOT NULL REFERENCES curated_collections(id), artwork_id uuid NOT NULL REFERENCES artworks(id), sort_order int DEFAULT 0, PRIMARY KEY(collection_id,artwork_id));
CREATE TABLE saved_items (user_id text NOT NULL REFERENCES "user"(id), subject_type text NOT NULL CHECK(subject_type IN ('ARTWORK','OPEN_CALL')), subject_id uuid NOT NULL, created_at timestamptz DEFAULT now(), PRIMARY KEY(user_id,subject_type,subject_id));
CREATE TABLE content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL CHECK(type IN ('ARTICLE','PAGE','EVENT','AUCTION','ARCHIVE','FAQ','ANNOUNCEMENT')), title text NOT NULL, slug text UNIQUE NOT NULL, body text NOT NULL, excerpt text NOT NULL DEFAULT '', visibility text NOT NULL DEFAULT 'PUBLIC', status text NOT NULL DEFAULT 'DRAFT', seo_title text NOT NULL DEFAULT '', seo_description text NOT NULL DEFAULT '', source_url text, event_at timestamptz, event_address text, capacity int CHECK(capacity>0), priority int NOT NULL DEFAULT 0, updated_by text REFERENCES "user"(id), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE event_rsvps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES content(id), user_id text NOT NULL REFERENCES "user"(id), status text NOT NULL DEFAULT 'REQUESTED', created_at timestamptz DEFAULT now(), UNIQUE(event_id,user_id));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id text NOT NULL REFERENCES "user"(id), type text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz DEFAULT now());
CREATE INDEX notification_recipient_idx ON notifications(recipient_id,read_at);
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id text REFERENCES "user"(id), type text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts int NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz DEFAULT now(), delivered_at timestamptz);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id text REFERENCES "user"(id), subject_type text NOT NULL, subject_id text NOT NULL, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_subject_idx ON audit_events(subject_type,subject_id,at);
CREATE TABLE rate_limits (key text PRIMARY KEY, count int NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL);
CREATE TABLE rate_limit (id text PRIMARY KEY, key text UNIQUE NOT NULL, count int NOT NULL, last_request bigint NOT NULL);
